import { ExpenseForm } from '../ExpenseForm/ExpenseForm'
import { useExpenses } from '../useExpenses/useExpenses'

export const ExpensesPage = () => {
  const { expenses, loading, loadError, submit } = useExpenses()

  return (
    <main>
      <h1>My expenses</h1>
      {loading && <p>Loading…</p>}
      {loadError && <p role="alert">Could not load your expenses.</p>}
      {!loading && !loadError && expenses.length === 0 && <p>No expenses yet.</p>}
      <ul>
        {expenses.map((expense) => (
          <li key={expense.id}>
            {expense.label} — {expense.amount} {expense.currency} ({expense.status})
          </li>
        ))}
      </ul>
      <h2>New expense</h2>
      <ExpenseForm onSubmit={submit} />
    </main>
  )
}
